+#[inline]
+fn slice_hash(slice: &[u8], hash_index: u64) -> u64 {
+    // Same result as `FnvHasher::with_key(hash_index)` fed `slice`, but
+    // reading eight bytes at a time.
+    const FNV_PRIME: u64 = 0x100000001b3;
+    let mut hash = hash_index;
+    let mut chunks = slice.chunks_exact(8);
+    for chunk in &mut chunks {
+        let mut word = u64::from_le_bytes(chunk.try_into().unwrap());
+        for _ in 0..8 {
+            hash ^= word & 0xff;
+            hash = hash.wrapping_mul(FNV_PRIME);
+            word >>= 8;
+        }
+    }
+    let mut hasher = FnvHasher::with_key(hash);
+    hasher.write(chunks.remainder());
+    hasher.finish()
+}

